```python
#!/usr/bin/env python3
"""Metadata-aware Retrieval-Augmented Generation (RAG) system.

  1. Indexes documents together with rich metadata (category, tags, author,
     date, year, audience, ...) into sparse TF-IDF semantic vectors.
  2. Filters candidates by structured metadata predicates BEFORE ranking.
  3. Ranks survivors with a hybrid relevance score:
         score = alpha * semantic_similarity
               + (1 - alpha) * metadata_relevance
     (semantic = cosine over TF-IDF; metadata = query/metadata token overlap
      blended with recency decay for dated documents).
  4. Generates a grounded answer from top-ranked passages with [n] citations
     and exposes source metadata.

Pure Python standard library; no network or third-party packages.
"""

from __future__ import annotations

import argparse
import datetime as _dt
import json
import math
import re
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

# ------------------------------- text utils --------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+")
_SENTENCE_RE = re.compile(r"(?<=[.!?])\s+")

_STOPWORDS = frozenset(
    """
    a an and are as at be but by for from has have he her his i if in is it its
    may more no not of on or our so than that the their them then there these
    they this to was we were what when which who will with you your the
    """.split()
)


def tokenize(text: object) -> List[str]:
    if text is None:
        return []
    return [t for t in _TOKEN_RE.findall(str(text).lower())
            if len(t) > 1 and t not in _STOPWORDS]


def _term_frequencies(tokens: Sequence[str]) -> Dict[str, int]:
    tf: Dict[str, int] = {}
    for tok in tokens:
        tf[tok] = tf.get(tok, 0) + 1
    return tf


def _sentences(text: str) -> List[str]:
    return [s.strip() for s in _SENTENCE_RE.split(text.strip()) if s.strip()]


def _parse_date(value: object):
    if isinstance(value, _dt.datetime):
        return value.date()
    if isinstance(value, _dt.date):
        return value
    if isinstance(value, str):
        for fmt in ("%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
            try:
                return _dt.datetime.strptime(value.strip()[:19], fmt).date()
            except ValueError:
                continue
        try:
            return _dt.date.fromisoformat(value.strip()[:10])
        except ValueError:
            return None
    return None

# --------------------------- metadata filter engine -------------------------

_ORDERED_OPS = {"gt", "gte", "lt", "lte"}


def _cmp_key(value: object):
    if isinstance(value, bool):
        return (0, int(value))
    if isinstance(value, (int, float)):
        return (1, float(value))
    s = str(value).strip()
    try:
        return (1, float(s))
    except ValueError:
        pass
    d = _parse_date(s)
    if d is not None:
        return (2, d)
    return (3, s.lower())


def _equal(a: object, b: object) -> bool:
    if a is None or b is None:
        return a is b
    if isinstance(a, bool) or isinstance(b, bool):
        return a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, (list, tuple, set)) and isinstance(b, (list, tuple, set)):
        return list(a) == list(b)
    return str(a).strip().lower() == str(b).strip().lower()


def _contains(value: object, needle: object) -> bool:
    if isinstance(value, (list, tuple, set)):
        return any(_equal(item, needle) or _contains(str(item), needle)
                   for item in value)
    return str(needle).strip().lower() in str(value).lower()


def _op_match(value: object, op: str, expected: object) -> bool:
    if op == "exists":
        return (value is not None) == bool(expected)
    if op == "eq":
        return _equal(value, expected)
    if op == "ne":
        return not _equal(value, expected)
    if op == "in":
        return any(_equal(value, item) for item in (expected or []))
    if op == "contains":
        return False if value is None else _contains(value, expected)
    if op in _ORDERED_OPS:
        if value is None:
            return False
        ka, kb = _cmp_key(value), _cmp_key(expected)
        if ka[0] != kb[0]:           # no ordering across incompatible kinds
            return False
        return {"gt": ka[1] > kb[1], "gte": ka[1] >= kb[1],
                "lt": ka[1] < kb[1], "lte": ka[1] <= kb[1]}[op]
    raise ValueError(f"unsupported filter operator: {op!r}")


def matches_filters(metadata: Dict[str, object], filters: Optional[dict]) -> bool:
    """True when metadata satisfies every predicate in filters.

    Grammar:
      {"category": "security"}                       equality
      {"year": {"gte": 2023}}                        numeric/date range
      {"tags": {"contains": "encryption"}}           substring / any member
      {"tags": {"in": ["sql", "cache"]}}             membership
      {"doc_type": {"exists": True}}                 presence
    """
    if not filters:
        return True
    for field, spec in filters.items():
        value = metadata.get(field)
        if isinstance(spec, dict) and set(spec.keys()) <= {
                "eq", "ne", "in", "contains", "exists", *_ORDERED_OPS}:
            for op, expected in spec.items():
                if not _op_match(value, op, expected):
                    return False
        elif isinstance(spec, (list, tuple, set)):
            if not any(_equal(value, item) for item in spec):
                return False
        elif not _equal(value, spec):
            return False
    return True

# ------------------------------ document model ------------------------------

@dataclass
class Document:
    doc_id: str
    text: str
    metadata: Dict[str, object] = field(default_factory=dict)
    tokens: List[str] = field(default_factory=list, repr=False)
    vector: Optional[Dict[str, float]] = field(default=None, repr=False)

    def __post_init__(self) -> None:
        if not self.tokens:
            self.tokens = tokenize(self.text)

    def to_public_dict(self, score: float) -> Dict[str, object]:
        return {
            "doc_id": self.doc_id,
            "score": round(score, 6),
            "title": self.metadata.get("title"),
            "category": self.metadata.get("category"),
            "tags": self.metadata.get("tags"),
            "author": self.metadata.get("author"),
            "date": self.metadata.get("date"),
            "metadata": dict(self.metadata),
        }

# ---------------- index with metadata filtering + hybrid ranking ------------

DEFAULT_BOOST_FIELDS = ("title", "tags", "category", "author", "audience")


class MetadataRAGIndex:
    """In-memory document index with metadata filtering and hybrid ranking."""

    def __init__(self, alpha: float = 0.65):
        if not 0.0 <= alpha <= 1.0:
            raise ValueError("alpha must be in [0, 1]")
        self.alpha = alpha
        self.documents: List[Document] = []
        self._idf: Dict[str, float] = {}
        self._built = False

    def add_document(self, doc: Document) -> None:
        self.documents.append(doc)
        self._built = False

    def add_documents(self, docs: Iterable[Document]) -> None:
        for doc in docs:
            self.add_document(doc)

    def build(self) -> None:
        if self._built:
            return
        n = len(self.documents)
        df: Dict[str, int] = {}
        for doc in self.documents:
            for term in set(doc.tokens):
                df[term] = df.get(term, 0) + 1
        self._idf = {t: math.log((1.0 + n) / (1.0 + freq)) + 1.0
                     for t, freq in df.items()}
        for doc in self.documents:
            doc.vector = self._vectorize(doc.tokens)
        self._built = True

    def _vectorize(self, tokens: Sequence[str]) -> Dict[str, float]:
        tf = _term_frequencies(tokens)
        vec: Dict[str, float] = {}
        norm = 0.0
        for term, freq in tf.items():
            w = freq * self._idf.get(term, 1.0)
            vec[term] = w
            norm += w * w
        if norm > 0.0:
            inv = math.sqrt(norm)
            vec = {t: w / inv for t, w in vec.items()}
        return vec

    @staticmethod
    def _cosine(a: Dict[str, float], b: Dict[str, float]) -> float:
        if not a or not b:
            return 0.0
        small, large = (a, b) if len(a) <= len(b) else (b, a)
        return sum(w * large.get(t, 0.0) for t, w in small.items())

    def _metadata_field_similarity(self, doc: Document, query_terms,
                                   boost_fields) -> float:
        if not query_terms:
            return 0.0
        field_scores: List[float] = []
        for field in boost_fields:
            raw = doc.metadata.get(field)
            if raw is None:
                continue
            values = raw if isinstance(raw, (list, tuple, set)) else [raw]
            best = 0.0
            for value in values:
                vt = set(tokenize(value))
                if not vt:
                    continue
                best = max(best, len(vt & query_terms) / float(len(vt)))
            field_scores.append(best)
        if not field_scores:
            return 0.0
        return sum(field_scores) / float(len(field_scores))

    def _recency(self, doc: Document, recency_field: Optional[str],
                 halflife_days: float, today: _dt.date) -> float:
        if not recency_field:
            return 1.0
        parsed = _parse_date(doc.metadata.get(recency_field))
        if parsed is None:
            return 1.0
        age_days = max(0.0, float((today - parsed).days))
        return 0.5 ** (age_days / halflife_days)

    def metadata_relevance(self, doc: Document, query_terms,
                           boost_fields=DEFAULT_BOOST_FIELDS,
                           recency_field: Optional[str] = "date",
                           halflife_days: float = 730.0,
                           today: Optional[_dt.date] = None) -> float:
        today = today or _dt.date.today()
        field_sim = self._metadata_field_similarity(doc, query_terms, boost_fields)
        recency = self._recency(doc, recency_field, halflife_days, today)
        return 0.75 * field_sim + 0.25 * recency

    def retrieve(self, query: str, *,
                 filters: Optional[dict] = None,
                 top_k: int = 5,
                 alpha: Optional[float] = None,
                 boost_fields=DEFAULT_BOOST_FIELDS,
                 recency_field: Optional[str] = "date",
                 halflife_days: float = 730.0,
                 today: Optional[_dt.date] = None) -> List[Tuple[float, Document]]:
        """Stage 1 metadata filtering -> Stage 2 hybrid relevance ranking."""
        if not self._built:
            self.build()
        if top_k <= 0:
            return []
        query_terms = set(tokenize(query))
        qvec = self._vectorize(tokenize(query))
        mix = self.alpha if alpha is None else alpha
        today = today or _dt.date.today()

        scored: List[Tuple[float, int, Document]] = []
        for idx, doc in enumerate(self.documents):
            if not matches_filters(doc.metadata, filters):
                continue                       # metadata gate
            semantic = self._cosine(qvec, doc.vector)
            meta = self.metadata_relevance(
                doc, query_terms, boost_fields=boost_fields,
                recency_field=recency_field, halflife_days=halflife_days,
                today=today)
            score = mix * semantic + (1.0 - mix) * meta
            scored.append((score, idx, doc))

        scored.sort(key=lambda item: (-item[0], item[1]))
        return [(score, doc) for score, _idx, doc in scored[:top_k]]

    def search(self, query: str, **kwargs) -> List[Tuple[float, Document]]:
        return self.retrieve(query, **kwargs)

# ----------------------- grounded answer generation -------------------------

class GroundedAnswerGenerator:
    """Deterministic extractive generator answering only from retrieved docs.

    Swap for an LLM call in production; the retrieval contract is unchanged.
    """

    def __init__(self, max_sentences_per_doc: int = 2):
        self.max_sentences_per_doc = max_sentences_per_doc

    def generate(self, question: str,
                 ranked: Sequence[Tuple[float, Document]]) -> str:
        if not ranked:
            return "No grounded evidence was retrieved for this question."
        query_terms = set(tokenize(question))
        lines: List[str] = []
        for rank, (_score, doc) in enumerate(ranked, start=1):
            candidates = []
            for sentence in _sentences(doc.text):
                st = set(tokenize(sentence))
                overlap = float(len(st & query_terms)) if st else 0.0
                candidates.append((overlap, sentence))
            candidates.sort(key=lambda c: (-c[0], len(c[1])))
            chosen = 0
            for _overlap, sentence in candidates:
                if chosen >= self.max_sentences_per_doc:
                    break
                lines.append(f"[{rank}] {sentence}")
                chosen += 1
            if chosen == 0:
                first = _sentences(doc.text)
                if first:
                    lines.append(f"[{rank}] {first[0]}")
        return "Based on the retrieved documents:\n" + "\n".join(lines)


class RAGPipeline:
    """End-to-end: metadata-filtered retrieval -> grounded, cited answer."""

    def __init__(self, index: MetadataRAGIndex,
                 generator: Optional[GroundedAnswerGenerator] = None,
                 top_k: int = 3):
        self.index = index
        self.generator = generator or GroundedAnswerGenerator()
        self.top_k = top_k

    def ask(self, question: str, *, filters: Optional[dict] = None,
            top_k: Optional[int] = None, **retrieve_kwargs) -> Dict[str, object]:
        top_k = top_k or self.top_k
        ranked = self.index.retrieve(question, filters=filters, top_k=top_k,
                                     **retrieve_kwargs)
        answer = self.generator.generate(question, ranked)
        return {
            "question": question,
            "filters": filters,
            "top_k": top_k,
            "answer": answer,
            "sources": [doc.to_public_dict(score) for score, doc in ranked],
        }

# ------------------------------ demo corpus ---------------------------------

def _doc(doc_id, title, category, tags, author, date, audience, body) -> Document:
    return Document(
        doc_id=doc_id,
        text=title + ". " + body,
        metadata={"title": title, "category": category, "tags": list(tags),
                  "author": author, "date": date, "year": int(date[:4]),
                  "audience": audience},
    )


def build_demo_index() -> MetadataRAGIndex:
    docs = [
        _doc("sec-001", "OAuth2 bearer token authentication for public APIs",
             "security", ["authentication", "tokens"], "alice", "2022-03-01",
             "developers",
             "Clients authenticate by presenting an OAuth2 bearer token in the "
             "Authorization header. Tokens are short-lived and scoped to the "
             "permissions the application requested during consent."),
        _doc("api-014", "Authenticating REST API calls with API keys",
             "api", ["authentication", "rest"], "bob", "2023-06-15",
             "developers",
             "Server-to-server integrations use static API keys sent in the "
             "X-API-Key header. Keys are issued per environment and can be "
             "rotated without invalidating other clients."),
        _doc("db-002", "Indexing strategies for PostgreSQL",
             "database", ["sql", "indexing"], "carol", "2021-11-20", "backend",
             "B-tree indexes accelerate equality and range lookups, while GIN "
             "indexes speed up full-text and array queries. Measure index "
             "bloat before adding new indexes to hot tables."),
        _doc("sec-004", "Encrypting data in transit with TLS 1.3",
             "security", ["encryption", "tls"], "alice", "2024-01-10",
             "platform",
             "All public endpoints require TLS 1.3 with strong cipher suites. "
             "Certificates are issued through the internal CA and auto-renewed "
             "thirty days before expiry."),
        _doc("api-021", "Rate limiting your public REST API",
             "api", ["rate-limiting", "rest"], "dave", "2024-02-18",
             "developers",
             "Every API key receives a fixed quota per minute. Excess calls "
             "receive HTTP 429 with a Retry-After header telling the caller "
             "when the window resets."),
        _doc("db-009", "Caching query results in Redis",
             "database", ["cache", "performance"], "carol", "2023-09-02",
             "backend",
             "Frequently executed read queries cache their results in Redis "
             "with a short TTL. The cache is invalidated on writes to the "
             "underlying tables to keep responses fresh."),
        _doc("sec-007", "Vulnerability patching policy",
             "security", ["patching", "policy"], "erin", "2020-05-30",
             "platform",
             "Critical vulnerabilities are patched within 72 hours and "
             "high-severity issues within two weeks. Patch windows require "
             "approval from the security lead before change freeze."),
        _doc("api-002", "Semantic versioning for REST endpoints",
             "api", ["versioning", "contract"], "bob", "2022-08-09",
             "developers",
             "We release new endpoint capabilities on a regular cadence. Each "
             "endpoint declares a stable release date and clients pin the "
             "major version they rely on. Breaking changes are communicated "
             "well in advance on the changelog."),
        _doc("front-001", "Managing user sessions in the web client",
             "frontend", ["auth", "sessions"], "frank", "2023-12-05",
             "frontend",
             "The web client keeps an in-memory session after login and "
             "refreshes the access token in the background before expiry. "
             "Logout clears both the local session and the server cookie."),
        _doc("db-012", "Automated database backup and recovery",
             "database", ["backups", "recovery"], "carol", "2024-04-22",
             "backend",
             "Full backups run nightly with point-in-time recovery enabled. "
             "Recovery drills execute quarterly and restore into isolated "
             "staging environments before production cutover."),
    ]
    index = MetadataRAGIndex(alpha=0.65)
    index.add_documents(docs)
    index.build()
    return index

# ------------------------------- self tests ---------------------------------

def run_self_tests() -> int:
    failures: List[str] = []

    def check(name, condition, detail=""):
        if condition:
            print(f"  PASS  {name}")
        else:
            failures.append(name)
            print(f"  FAIL  {name}  {detail}")

    print("Running self-tests ...")
    index = build_demo_index()

    check("tokenize drops stopwords",
          tokenize("The quick brown fox") == ["quick", "brown", "fox"])
    check("term frequencies",
          _term_frequencies(["a", "b", "a"]) == {"a": 2, "b": 1})

    filters = {"category": "security",
               "tags": {"contains": "encryption"},
               "year": {"gte": 2023}}
    allowed = {d.doc_id for d in index.documents
               if matches_filters(d.metadata, filters)}
    check("metadata filter selects exactly sec-004",
          allowed == {"sec-004"}, f"got {sorted(allowed)}")

    ranked = index.retrieve("encrypt data in transit", filters=filters, top_k=5)
    ranked_ids = [d.doc_id for _s, d in ranked]
    check("filtered retrieval returns only matching docs",
          set(ranked_ids) <= allowed and len(ranked_ids) == 1,
          f"got {ranked_ids}")
    check("expected doc ranks first under filter",
          ranked_ids and ranked_ids[0] == "sec-004", f"got {ranked_ids}")

    all_ranked = index.retrieve("how should clients authenticate to the api",
                                top_k=len(index.documents))
    scores = [s for s, _d in all_ranked]
    check("ranking is strictly non-increasing",
          all(a >= b for a, b in zip(scores, scores[1:])))
    check("top_k is respected", len(all_ranked) == len(index.documents))

    sim_only = index.retrieve("contract", filters={"category": "api"}, alpha=1.0)
    hybrid = index.retrieve("contract", filters={"category": "api"}, alpha=0.35)
    check("hybrid metadata ranking promotes tag-matched doc",
          hybrid[0][1].doc_id == "api-002" and sim_only[0][1].doc_id != "api-002",
          f"sim_only={[d.doc_id for _s, d in sim_only]} "
          f"hybrid={[d.doc_id for _s, d in hybrid]}")

    recent = index.retrieve("recovery", filters={"category": "database"},
                            alpha=0.5, recency_field="date")
    check("recent doc ranks above older doc within hybrid mix",
          recent[0][1].doc_id == "db-012",
          f"got {[d.doc_id for _s, d in recent]}")

    pipeline = RAGPipeline(index, top_k=2)
    result = pipeline.ask("how do we protect traffic to public endpoints?",
                          filters={"category": "security"})
    answer = str(result["answer"]); sources = list(result["sources"])
    check("pipeline returns grounded answer with citations",
          "[1]" in answer and "[2]" in answer, answer)
    check("pipeline exposes source metadata",
          all(s.get("metadata", {}).get("category") == "security"
              for s in sources))
    check("top source is the TLS guidance",
          sources and sources[0]["doc_id"] == "sec-004",
          f"got {[s['doc_id'] for s in sources]}")

    if failures:
        print(f"Self-tests FAILED ({len(failures)}): {failures}")
        return 1
    print("Self-tests passed.")
    return 0

# ----------------------------------- CLI ------------------------------------

def run_demo() -> None:
    print("Demo corpus: 10 internal knowledge-base documents (security / api / "
          "database / frontend) with title, category, tags, author, date, "
          "year, audience metadata.")
    index = build_demo_index()
    pipeline = RAGPipeline(index, top_k=3)

    scenarios = [
        ("Q1 unrestricted: how should clients authenticate to the API?", None),
        ("Q2 filtered: category=security AND tags contain 'encryption'",
         {"category": "security", "tags": {"contains": "encryption"}}),
        ("Q3 filtered: category=api AND year >= 2023",
         {"category": "api", "year": {"gte": 2023}}),
        ("Q4 filtered: category=database AND tags in [cache, backups]",
         {"category": "database", "tags": {"in": ["cache", "backups"]}}),
    ]
    for label, filters in scenarios:
        question = label.split(":", 1)[1].strip()
        print("\n" + "=" * 78)
        print(label)
        result = pipeline.ask(question, filters=filters)
        print(f"Question : {result['question']}")
        print(f"Filters  : {json.dumps(result['filters'])}")
        print("Ranked documents (metadata-filtered, relevance-ranked):")
        for i, source in enumerate(result["sources"], start=1):
            meta = source["metadata"]
            print(f"  {i}. [{source['doc_id']}] score={source['score']}")
            print(f"      title    : {meta['title']}")
            print(f"      category : {meta['category']}  tags={meta['tags']}")
            print(f"      author   : {meta['author']}  date={meta['date']}")
        print("Grounded answer:")
        for line in str(result["answer"]).splitlines():
            print(f"  {line}")


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="Metadata-aware RAG system (filtering + relevance ranking).")
    parser.add_argument("--mode", choices=("all", "demo", "test"),
                        default="all")
    args = parser.parse_args(argv)
    if args.mode in ("all", "test"):
        code = run_self_tests()
        if code != 0:
            return code
    if args.mode in ("all", "demo"):
        run_demo()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

## Usage

```
python3 rag_system.py            # self-tests + demo queries
python3 rag_system.py --mode test
python3 rag_system.py --mode demo
```

The demo exercises exactly what the task asks for: unrestricted retrieval (Q1), metadata-filtered retrieval with equality + `contains` (Q2), date-range filtering via `year gte` (Q3), tag-membership filtering (Q4), and each result set is ranked by the hybrid relevance score and answered only from the retrieved, metadata-carrying sources.

**Honest limitation:** because the sandbox denied the workspace write, this artifact is delivered inline rather than committed, and its self-test suite was not executed in this environment. If you can enable `write_file` in the workspace (or run this code in any Python 3.8+ interpreter), it is ready to use as-is.

