# ----------------------------------------------------------------------------
# Reporting helpers
# ----------------------------------------------------------------------------

def _fmt_filter_value(v) -> str:
    if isinstance(v, list):
        return "[" + ", ".join(str(x) for x in v) + "]"
    return str(v)


def format_filters(filters: dict) -> str:
    if not filters:
        return "none (all documents eligible)"
    bits = []
    for key in sorted(filters):
        spec = filters[key]
        if isinstance(spec, dict) and spec and all(k.startswith("$") for k in spec):
            inner = " AND ".join("%s %s" % (op, _fmt_filter_value(spec[op]))
                                 for op in sorted(spec))
            bits.append("%s: %s" % (key, inner))
        else:
            bits.append("%s: %s" % (key, _fmt_filter_value(spec)))
    return " AND ".join(bits)


def _short(text: str, n: int = 96) -> str:
    text = _clean(text)
    return text if len(text) <= n else text[: n - 3] + "..."


def print_hits(hits, label: str = "Ranked hits"):
    print("  %s:" % label)
    if not hits:
        print("    (no documents returned)")
        return
    for h in hits:
        m = h.chunk.metadata
        tags = ", ".join(m.get("tags", []))
        print("    #%d  hybrid=%.3f  dense=%.3f + sparse=%.3f  %s | %s | lvl=%s | %s"
              % (h.rank, h.hybrid, h.dense, h.sparse, h.chunk.doc_id,
                 m.get("title"), m.get("access_level"), m.get("date")))
        print("        src=%s | cat=%s | tags=%s" % (m.get("source"), m.get("category"), tags))
        print("        excerpt: %s" % _short(h.chunk.text, 130))


def print_report(report: QueryReport, show_citations: bool = True):
    ans = report.answer
    print("  Question : %s" % report.query)
    print("  Filters  : %s" % format_filters(report.filters))
    print_hits(report.hits)
    print("  Answer (%s, %d chunks, %d chars context, conf=%.2f, grounded=%.2f):"
          % (ans.mode, ans.num_chunks, ans.context_chars, ans.confidence, ans.groundedness))
    print("    %s" % ans.text)
    if show_citations and ans.citations:
        print("  Sources:")
        for c in ans.citations:
            print("    %s" % c)
    print()


