#!/usr/bin/env python3
"""
Metadata-filtered RAG system with relevance ranking.

A self-contained Retrieval-Augmented Generation pipeline that demonstrates:

  1. Indexing:      document -> chunking (word-window with overlap), each chunk
                    inherits rich metadata (category, tags, access_level, date,
                    author, source, title).
  2. Retrieval:     metadata filtering (equality, list membership, substring,
                    numeric/date ranges) applied BEFORE ranking.
  3. Ranking:       hybrid relevance = w_d * dense_sim + w_s * sparse_bm25,
                    where dense_sim comes from hash-based pseudo-embeddings
                    (deterministic, no external model) and sparse is BM25.
  4. Reranking:     optional Maximal Marginal Relevance (MMR) for diversity.
  5. Generation:    grounded extractive answer synthesis that only uses the
                    retrieved context and attaches citation markers [n].
  6. Evaluation:    recall@k and MRR over labeled query -> doc_id cases.

The extractive generator is a deterministic stand-in so the whole demo runs
offline with zero third-party dependencies. To use a real LLM you would swap
`generate()` for a call to any chat-completions API with a prompt that injects
{context} built from the ranked hits, then return the model text.

Run:  python3 rag_metadata_system.py
"""

from __future__ import annotations

import hashlib
import math
import re
import statistics
import sys
from collections import Counter
from dataclasses import dataclass, field
from datetime import date

# ----------------------------------------------------------------------------
# Text utilities
# ----------------------------------------------------------------------------

_clean_re = re.compile(r"\s+")


def _clean(text: str) -> str:
    return _clean_re.sub(" ", text).strip()


def _sentences(text: str) -> list:
    parts = re.split(r"(?<=[.!?])\s+", _clean(text))
    out = [p for p in (p.strip() for p in parts) if p]
    return out or ([_clean(text)] if text.strip() else [])


def _stem(word: str) -> str:
    """Light, deterministic suffix normaliser applied to both sides."""
    w = word.lower()
    if len(w) <= 3:
        return w
    if w.endswith("ing") and len(w) > 5:
        w = w[:-3]
    elif w.endswith("ies") and len(w) > 4:
        w = w[:-3] + "y"
    elif w.endswith("es") and len(w) > 4 and not w.endswith("sses"):
        w = w[:-2]
    elif w.endswith("ed") and len(w) > 4:
        w = w[:-2]
    elif w.endswith("s") and len(w) > 3 and not w.endswith(("ss", "us", "is")):
        w = w[:-1]
    if w.endswith("e") and len(w) > 4 and not w.endswith(("ee", "le", "ge", "ce", "se")):
        w = w[:-1]
    return w


def tokenize(text: str) -> list:
    toks = re.findall(r"[A-Za-z0-9]+(?:[._-][A-Za-z0-9]+)*", text.lower())
    return [_stem(t) for t in toks]


def chunk_text(text: str, chunk_words: int = 120, overlap_words: int = 20,
               min_tail: int = 30) -> list:
    """Word-window chunking with overlap; short tails merge into last chunk."""
    words = text.split()
    if not words:
        return []
    if len(words) <= chunk_words:
        return [" ".join(words)]
    chunks, start, n = [], 0, len(words)
    while start < n:
        if n - start < min_tail and chunks:
            chunks[-1] += " " + " ".join(words[start:])
            break
        end = min(start + chunk_words, n)
        chunks.append(" ".join(words[start:end]))
        if end >= n:
            break
        start = max(end - overlap_words, start + 1)
    return chunks


# ----------------------------------------------------------------------------
# Dense similarity stand-in: signed feature hashing into a fixed-dim vector
# ----------------------------------------------------------------------------

class PseudoEmbeddings:
    """Deterministic hash embeddings (words + character 3-grams).

    No external model or API: identical strings always map to identical
    vectors, and lexically/semantically related passages share hashed
    features, which is enough to demonstrate dense retrieval mechanics.
    """

    def __init__(self, dim: int = 1024):
        self.dim = dim

    def embed(self, text: str) -> list:
        vec = [0.0] * self.dim
        words = re.findall(r"[a-z0-9]+(?:[._-][a-z0-9]+)*", text.lower())
        for w in words:
            if not w:
                continue
            if len(w) >= 2:
                self._add(vec, "w:" + w, 3.0)
            if len(w) >= 3:
                for i in range(len(w) - 2):
                    self._add(vec, "g:" + w[i:i + 3], 1.0)
        norm = math.sqrt(sum(x * x for x in vec))
        if norm:
            inv = 1.0 / norm
            return [x * inv for x in vec]
        return vec

    @staticmethod
    def _add(vec: list, token: str, weight: float) -> None:
        digest = hashlib.blake2b(token.encode("utf-8"), digest_size=8).digest()
        idx = int.from_bytes(digest[:4], "little") % len(vec)
        sign = 1.0 if digest[4] & 1 else -1.0
        vec[idx] += sign * weight

    @staticmethod
    def cosine(a: list, b: list) -> float:
        return sum(x * y for x, y in zip(a, b))


# ----------------------------------------------------------------------------
# Core data structures
# ----------------------------------------------------------------------------

@dataclass
class Chunk:
    chunk_id: str
    doc_id: str
    text: str
    metadata: dict
    terms: list = field(default_factory=list, compare=False, repr=False)
    term_freq: Counter = field(default_factory=Counter, compare=False, repr=False)
    length: int = 0
    vector: list = field(default_factory=list, compare=False, repr=False)


@dataclass
class RankedHit:
    rank: int
    chunk: Chunk
    dense: float          # normalized dense similarity score (0..1)
    sparse: float         # normalized BM25 score (0..1)
    hybrid: float         # weighted combination


@dataclass
class GeneratedAnswer:
    text: str
    citations: list
    num_chunks: int
    context_chars: int
    confidence: float
    groundedness: float
    mode: str


@dataclass
class QueryReport:
    query: str
    filters: dict
    hits: list
    answer: GeneratedAnswer


# ----------------------------------------------------------------------------
# The RAG engine
# ----------------------------------------------------------------------------

class MetadataRAG:
    """Indexes documents, filters by metadata, ranks by hybrid relevance,
    and generates grounded answers from the retrieved context."""

    def __init__(self, documents, chunk_words: int = 120, overlap_words: int = 20,
                 embed_dim: int = 1024, dense_weight: float = 0.5,
                 sparse_weight: float = 0.5):
        self.documents = {d["doc_id"]: d for d in documents}
        self.chunk_words = chunk_words
        self.overlap_words = overlap_words
        self.dense_weight = dense_weight
        self.sparse_weight = sparse_weight
        self.k1 = 1.5
        self.b = 0.75
        self.embedder = PseudoEmbeddings(dim=embed_dim)
        self.chunks: list = []
        self.idf: dict = {}
        self.avgdl = 0.0
        self._index(documents)

    # ---------------------------------------------------------------- indexing
    def _index(self, documents) -> None:
        for doc in documents:
            doc_id = doc["doc_id"]
            texts = chunk_text(doc.get("content", ""), self.chunk_words, self.overlap_words)
            base = {k: v for k, v in doc.items() if k not in ("content", "doc_id")}
            for i, text in enumerate(texts):
                meta = dict(base)
                meta["doc_id"] = doc_id
                meta["chunk_index"] = i
                self.chunks.append(Chunk(
                    chunk_id="%s#c%d" % (doc_id, i),
                    doc_id=doc_id,
                    text=_clean(text),
                    metadata=meta,
                ))
        for c in self.chunks:
            c.terms = tokenize(c.text)
            c.term_freq = Counter(c.terms)
            c.length = len(c.terms)
            c.vector = self.embedder.embed(c.text)
        n = len(self.chunks)
        df = Counter()
        for c in self.chunks:
            df.update(set(c.terms))
        self.idf = {t: math.log(1 + (n - cnt + 0.5) / (cnt + 0.5)) for t, cnt in df.items()}
        self.avgdl = (sum(c.length for c in self.chunks) / n) if n else 0.0

    def stats(self) -> dict:
        by_cat = Counter(c.metadata["category"] for c in self.chunks)
        return {
            "documents": len(self.documents),
            "chunks": len(self.chunks),
            "chunks_per_doc": {d: sum(1 for c in self.chunks if c.doc_id == d)
                               for d in sorted(self.documents)},
            "vocab_terms": len(self.idf),
            "avg_chunk_tokens": round(self.avgdl, 1),
            "chunks_by_category": dict(by_cat),
            "metadata_fields": sorted(k for k in self.chunks[0].metadata) if self.chunks else [],
        }

    # ---------------------------------------------------------- metadata logic
    @staticmethod
    def _kind(value):
        if isinstance(value, bool):
            return ("num", 1.0 if value else 0.0)
        if isinstance(value, (int, float)):
            return ("num", float(value))
        if isinstance(value, date):
            return ("date", value)
        if isinstance(value, str):
            s = value.strip()
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
                return ("date", date.fromisoformat(s))
            if re.fullmatch(r"-?\d+(\.\d+)?", s):
                return ("num", float(s))
            return ("str", s.lower())
        return ("raw", value)

    @classmethod
    def _cmp(cls, a, b):
        ka, va = cls._kind(a)
        kb, vb = cls._kind(b)
        if ka == kb and ka in ("num", "date"):
            return (va > vb) - (va < vb)
        if ka == "str" and kb == "str":
            return (va > vb) - (va < vb)
        s1, s2 = str(a).lower(), str(b).lower()
        return (s1 > s2) - (s1 < s2)

    @classmethod
    def _eq(cls, a, b) -> bool:
        if a is None or b is None:
            return a is None and b is None
        ka, _ = cls._kind(a)
        kb, _ = cls._kind(b)
        if ka == kb and ka in ("num", "date"):
            return cls._cmp(a, b) == 0
        return str(a).lower() == str(b).lower()

    def _eval_op(self, op: str, value, target) -> bool:
        if op in ("$gt", "$gte", "$lt", "$lte"):
            if value is None:
                return False
            c = self._cmp(value, target)
            return {"$gt": c > 0, "$gte": c >= 0, "$lt": c < 0, "$lte": c <= 0}[op]
        if op == "$eq":
            return self._eq(value, target)
        if op == "$ne":
            return not self._eq(value, target)
        if op == "$in":
            if value is None:
                return False
            targets = target if isinstance(target, list) else [target]
            values = value if isinstance(value, list) else [value]
            return any(self._eq(v, t) for v in values for t in targets)
        if op == "$contains":
            if value is None:
                return False
            needle = str(target).lower()
            values = value if isinstance(value, list) else [value]
            return any(needle in str(v).lower() for v in values)
        raise ValueError("unsupported filter operator: %s" % op)

    def _match(self, metadata: dict, filters: dict) -> bool:
        for fname, spec in filters.items():
            value = metadata.get(fname)
            if isinstance(spec, dict) and spec and all(k.startswith("$") for k in spec):
                for op, target in spec.items():
                    if not self._eval_op(op, value, target):
                        return False
            elif isinstance(spec, list):
                if not self._eval_op("$in", value, spec):
                    return False
            else:
                if not self._eval_op("$eq", value, spec):
                    return False
        return True

    # ------------------------------------------------------------- retrieval
    @staticmethod
    def _minmax(scores: dict) -> dict:
        if not scores:
            return {}
        lo, hi = min(scores.values()), max(scores.values())
        if hi - lo < 1e-12:
            return {k: 1.0 for k in scores}
        return {k: (v - lo) / (hi - lo) for k, v in scores.items()}

    def _sim_between(self, i: int, j: int) -> float:
        return (self.embedder.cosine(self.chunks[i].vector, self.chunks[j].vector) + 1.0) / 2.0

    def _mmr_select(self, order, combined, lam: float, k: int):
        chosen, remaining = [], list(order)
        while remaining and len(chosen) < k:
            best_i, best_score = None, -1.0
            for idx in remaining:
                mx = max((self._sim_between(idx, j) for j in chosen), default=0.0)
                score = lam * combined[idx] - (1.0 - lam) * mx
                if score > best_score:
                    best_score, best_i = score, idx
            chosen.append(best_i)
            remaining.remove(best_i)
        return chosen + remaining

    def retrieve(self, query: str, top_k: int = 5, filters=None, weights=None,
                 diversify: bool = False, mmr_lambda: float = 0.6) -> list:
        """Metadata filter first, then hybrid dense+BM25 ranking (MMR optional)."""
        filters = filters or {}
        w_d = (weights or {}).get("dense", self.dense_weight)
        w_s = (weights or {}).get("sparse", self.sparse_weight)
        matched = [i for i, c in enumerate(self.chunks) if self._match(c.metadata, filters)]
        if not matched:
            return []

        qv = self.embedder.embed(query)
        q_terms = Counter(tokenize(query))

        dense_raw, sparse_raw = {}, {}
        for i in matched:
            dense_raw[i] = (self.embedder.cosine(self.chunks[i].vector, qv) + 1.0) / 2.0
            s = 0.0
            for t, f in q_terms.items():
                tf = self.chunks[i].term_freq.get(t, 0)
                if tf:
                    s += self.idf.get(t, 0.0) * tf * (self.k1 + 1.0) / (
                        tf + self.k1 * (1.0 - self.b + self.b * self.chunks[i].length / self.avgdl)
                    )
            sparse_raw[i] = s

        dense_n = self._minmax(dense_raw)
        sparse_n = self._minmax(sparse_raw)
        combined = {i: w_d * dense_n[i] + w_s * sparse_n[i] for i in matched}
        order = sorted(matched, key=lambda i: combined[i], reverse=True)
        if diversify and len(order) > 1:
            order = self._mmr_select(order, combined, mmr_lambda, min(top_k, len(order)))
        order = order[:top_k]

        hits = []
        for rank, i in enumerate(order, start=1):
            hits.append(RankedHit(rank=rank, chunk=self.chunks[i],
                                  dense=dense_n[i], sparse=sparse_n[i],
                                  hybrid=combined[i]))
        return hits

    # ------------------------------------------------------------- generation
    def generate(self, query: str, hits: list, max_chars: int = 360,
                 max_sentences: int = 4) -> GeneratedAnswer:
        """Grounded extractive synthesis: sentences come only from ranked hits."""
        if not hits:
            return GeneratedAnswer(
                text="No documents matched the requested metadata filters, so no "
                     "answer could be generated. Relax the filters or broaden the query.",
                citations=[], num_chunks=0, context_chars=0, confidence=0.0,
                groundedness=0.0, mode="empty-context")

        q_terms = set(tokenize(query))
        source_text = " ".join(h.chunk.text for h in hits)
        picks = []  # (rank, sentence)

        for h in hits:
            best_s, best_sc = None, 0.0
            for s in _sentences(h.chunk.text):
                ts = set(tokenize(s))
                overlap = q_terms & ts
                if not overlap:
                    continue
                sc = sum(self.idf.get(t, 1.0) for t in overlap) / max(1, len(ts))
                if sc > best_sc:
                    best_sc, best_s = sc, s
            if best_s:
                picks.append((h.rank, best_s))

        if not picks:  # no lexical overlap anywhere -> fall back to top hit head
            first = _sentences(hits[0].chunk.text)
            picks = [(hits[0].rank, first[0])] if first else [(hits[0].rank, hits[0].chunk.text[:180])]

        picks.sort(key=lambda p: p[0])
        parts, seen, used_chars = [], set(), 0
        for rank, s in picks:
            if len(seen) >= max_sentences:
                break
            clean_s = _clean(s)
            if used_chars + len(clean_s) + 6 > max_chars:
                continue
            key = clean_s.lower()[:60]
            if key in seen:
                continue
            seen.add(key)
            parts.append("%s [%d]" % (clean_s, rank))
            used_chars += len(clean_s) + 6

        text = " ".join(parts)
        citations = ["[%d] %s" % (rank, hits[rank - 1].chunk.metadata.get("source", ""))
                     for rank, _ in picks if 0 < rank <= len(hits)]
        # dedupe citations, keep order
        citations = list(dict.fromkeys(citations))

        confidence = round(statistics.mean(h.hybrid for h in hits), 3)
        source_tokens = set(tokenize(source_text))
        body_tokens = [t for t in tokenize(re.sub(r"\[\d+\]", "", text)) if t]
        grounded = (len([t for t in body_tokens if t in source_tokens]) / len(body_tokens)
                    if body_tokens else 1.0)

        return GeneratedAnswer(text=text, citations=citations, num_chunks=len(hits),
                               context_chars=sum(len(h.chunk.text) for h in hits),
                               confidence=confidence, groundedness=round(grounded, 3),
                               mode="extractive-grounded")

    def ask(self, query: str, top_k: int = 5, filters=None, weights=None,
            diversify: bool = False, mmr_lambda: float = 0.6) -> QueryReport:
        hits = self.retrieve(query, top_k=top_k, filters=filters, weights=weights,
                             diversify=diversify, mmr_lambda=mmr_lambda)
        return QueryReport(query=query, filters=filters or {}, hits=hits,
                           answer=self.generate(query, hits))

    # ------------------------------------------------------------- evaluation
    def evaluate(self, cases: list, k: int = 3) -> dict:
        rows = []
        for case in cases:
            hits = self.retrieve(case["query"], top_k=k, filters=case.get("filters"))
            ids = [h.chunk.doc_id for h in hits]
            expected = set(case["expected"])
            recall = len(expected & set(ids)) / len(expected)
            mrr = 0.0
            for pos, did in enumerate(ids, start=1):
                if did in expected:
                    mrr = 1.0 / pos
                    break
            rows.append({"query": case["query"], "expected": sorted(expected),
                         "returned": ids, "recall@%d" % k: round(recall, 2),
                         "mrr": round(mrr, 2)})
        return {"rows": rows,
                "mean_recall@%d" % k: round(statistics.mean(r["recall@%d" % k] for r in rows), 2),
                "mean_mrr": round(statistics.mean(r["mrr"] for r in rows), 2)}


