    print_report(rag.ask(q3, top_k=5,
                         filters={"category": ["engineering", "product"],
                                  "date": {"$gte": "2024-06-01"}}))

    # --- R5: access-control demonstration
    q4 = "What do we require for data classification, security access, and 2025 budget plans?"
    print("RUN 4a - caller has access_level<=2 over restricted categories (empty result)")
    print_report(rag.ask(q4, top_k=5,
                         filters={"category": ["research", "policies", "finance"],
                                  "access_level": {"$lte": 2}}))
    print("RUN 4b - same question WITHOUT the access filter (full candidate set)")
    print_report(rag.ask(q4, top_k=5,
                         filters={"category": ["research", "policies", "finance"]}))

    # --- R6: MMR diversity reranking
    q5 = "database performance, scaling, and analytics best practices"
    plain = rag.retrieve(q5, top_k=4)
    mmr = rag.retrieve(q5, top_k=4, diversify=True, mmr_lambda=0.55)
    def tag_set(hits):
        return sorted({t for h in hits for t in h.chunk.metadata.get("tags", [])})
    def doc_list(hits):
        return [h.chunk.doc_id for h in hits]
    print("RUN 5 - reranking: plain top-4 vs MMR top-4 (query: %r)" % q5)
    print("  plain top-4 docs=%s  unique_tags=%d  tags=%s"
          % (doc_list(plain), len(tag_set(plain)), tag_set(plain)))
    print("  mmr   top-4 docs=%s  unique_tags=%d  tags=%s"
          % (doc_list(mmr), len(tag_set(mmr)), tag_set(mmr)))
    print("  -> MMR trades a little relevance for topical diversity"
          if len(tag_set(mmr)) > len(tag_set(plain)) else "  -> MMR tie; corpus is small")
    print()


def main() -> int:
    docs = load_demo_corpus()
    rag = MetadataRAG(docs)
    overview(rag)
    run_self_tests(rag)
    eval_report(rag)
    demo_queries(rag)
    print("=" * 78)
    print("DONE: metadata-filtered RAG pipeline executed successfully.")
    print("=" * 78)
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Metadata-aware Retrieval-Augmented Generation (RAG) system.

This artifact implements a self-contained RAG retrieval layer that:

  1. Indexes documents together with rich metadata (category, tags, author,
     date, year, audience, title, ...) into sparse TF-IDF semantic vectors.
  2. Filters candidate documents by structured metadata predicates BEFORE any
     ranking (equality, membership, string containment, numeric/date ranges).
  3. Ranks the surviving candidates with a hybrid relevance score:

         score = alpha * semantic_similarity
               + (1 - alpha) * metadata_relevance

     where:
       * semantic_similarity  = cosine similarity between the TF-IDF vector
                                of the query and of the document text;
       * metadata_relevance   = token-overlap between the query and boostable
                                metadata fields (title, tags, category,
                                author, audience), blended with a recency
                                decay for dated documents.
  4. Generates a grounded answer from the top-ranked passages, citing the
     ranked source documents and exposing their metadata for transparency.

The implementation is pure Python standard library, so it runs in any
sandbox without network access or third-party packages.
"""

from __future__ import annotations

import argparse
import datetime as _dt
import json
import math
import re
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

# --------------------------------------------------------------------------
# Text utilities
# --------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"[a-z0-9]+")
_SENTENCE_RE = re.compile(r"(?<=[.!?])\s+")

_STOPWORDS = frozenset(
    """
    a an and are as at be but by for from has have he her his i if in is it its
    may more no not of on or our so than that the their them then there these
    they this to was we were what when which who will with you your the
    """.split()
)


def tokenize(text: object) -> List[str]:
    """Lowercase tokenization that drops stopwords and single characters."""
    if text is None:
        return []
    return [
        t
        for t in _TOKEN_RE.findall(str(text).lower())
        if len(t) > 1 and t not in _STOPWORDS
    ]


def _term_frequencies(tokens: Sequence[str]) -> Dict[str, int]:
    tf: Dict[str, int] = {}
    for tok in tokens:
        tf[tok] = tf.get(tok, 0) + 1
    return tf


def _sentences(text: str) -> List[str]:
    return [s.strip() for s in _SENTENCE_RE.split(text.strip()) if s.strip()]


def _parse_date(value: object):
    """Best-effort date parsing returning a datetime.date or None."""
    if isinstance(value, _dt.datetime):
        return value.date()
    if isinstance(value, _dt.date):
        return value
    if isinstance(value, str):
        for fmt in ("%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S"):
            try:
                return _dt.datetime.strptime(value.strip()[:19], fmt).date()
            except ValueError:
                continue
        try:
            return _dt.date.fromisoformat(value.strip()[:10])
        except ValueError:
            return None
    return None


# --------------------------------------------------------------------------
# Metadata filter engine
# --------------------------------------------------------------------------

_ORDERED_OPS = {"gt", "gte", "lt", "lte"}


def _cmp_key(value: object):
    """Normalise a value into a comparable key for ordered operators."""
    if isinstance(value, bool):
        return (0, int(value))
    if isinstance(value, (int, float)):
        return (1, float(value))
    s = str(value).strip()
    try:
        return (1, float(s))  # numeric-like strings, e.g. "2023"
    except ValueError:
        pass
    d = _parse_date(s)
    if d is not None:
        return (2, d)
    return (3, s.lower())


def _equal(a: object, b: object) -> bool:
    if a is None or b is None:
        return a is b
    if isinstance(a, bool) or isinstance(b, bool):
        return a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, (list, tuple, set)) and isinstance(b, (list, tuple, set)):
        return list(a) == list(b)
    return str(a).strip().lower() == str(b).strip().lower()


def _contains(value: object, needle: object) -> bool:
    if isinstance(value, (list, tuple, set)):
        return any(_equal(item, needle) or _contains(str(item), needle)
                   for item in value)
    return str(needle).strip().lower() in str(value).lower()


def _op_match(value: object, op: str, expected: object) -> bool:
    if op == "exists":
        return (value is not None) == bool(expected)
    if op == "eq":
        return _equal(value, expected)
    if op == "ne":
        return not _equal(value, expected)
    if op == "in":
        return any(_equal(value, item) for item in (expected or []))
    if op == "contains":
        if value is None:
            return False
        return _contains(value, expected)
    if op in _ORDERED_OPS:
        if value is None:
            return False
        ka, kb = _cmp_key(value), _cmp_key(expected)
        if ka[0] != kb[0]:
            # No meaningful ordering across incompatible kinds.
            return False
        if op == "gt":
            return ka[1] > kb[1]
        if op == "gte":
            return ka[1] >= kb[1]
        if op == "lt":
            return ka[1] < kb[1]
        if op == "lte":
            return ka[1] <= kb[1]
    raise ValueError(f"unsupported filter operator: {op!r}")


def matches_filters(metadata: Dict[str, object], filters: Optional[dict]) -> bool:
    """Return True when *metadata* satisfies every predicate in *filters*.

    Filter grammar (each key is a metadata field name):
        {"category": "security"}                        -> equality
        {"year": {"gte": 2023}}                         -> numeric/date range
        {"tags": {"contains": "encryption"}}            -> substring/any-member
        {"tags": {"in": ["sql", "cache"]}}              -> membership
        {"doc_type": {"exists": True}}                  -> presence check
    """
    if not filters:
        return True
    for field, spec in filters.items():
        value = metadata.get(field)
        if isinstance(spec, dict) and set(spec.keys()) <= {
                "eq", "ne", "in", "contains", "exists", *_ORDERED_OPS}:
            for op, expected in spec.items():
                if not _op_match(value, op, expected):
                    return False
        elif isinstance(spec, (list, tuple, set)):
            if not any(_equal(value, item) for item in spec):
                return False
        elif not _equal(value, spec):
            return False
    return True


# --------------------------------------------------------------------------
# Document model
# --------------------------------------------------------------------------

@dataclass
class Document:
    doc_id: str
    text: str
    metadata: Dict[str, object] = field(default_factory=dict)
    tokens: List[str] = field(default_factory=list, repr=False)
    vector: Optional[Dict[str, float]] = field(default=None, repr=False)

    def __post_init__(self) -> None:
        if not self.tokens:
            self.tokens = tokenize(self.text)

    def to_public_dict(self, score: float) -> Dict[str, object]:
        return {
            "doc_id": self.doc_id,
            "score": round(score, 6),
            "title": self.metadata.get("title"),
            "category": self.metadata.get("category"),
            "tags": self.metadata.get("tags"),
            "author": self.metadata.get("author"),
            "date": self.metadata.get("date"),
            "metadata": dict(self.metadata),
        }


# --------------------------------------------------------------------------
# Index + metadata-filtered retrieval with hybrid relevance ranking
# --------------------------------------------------------------------------

DEFAULT_BOOST_FIELDS = ("title", "tags", "category", "author", "audience")


class MetadataRAGIndex:
    """In-memory document index with metadata filtering and hybrid ranking."""

    def __init__(self, alpha: float = 0.65):
        if not 0.0 <= alpha <= 1.0:
            raise ValueError("alpha must be in [0, 1]")
        self.alpha = alpha
        self.documents: List[Document] = []
        self._idf: Dict[str, float] = {}
        self._built = False

    # -- ingestion ---------------------------------------------------------
    def add_document(self, doc: Document) -> None:
        self.documents.append(doc)
        self._built = False

    def add_documents(self, docs: Iterable[Document]) -> None:
        for doc in docs:
            self.add_document(doc)

    def build(self) -> None:
        """Compute corpus IDF statistics and semantic vectors for all docs."""
        if self._built:
            return
        n = len(self.documents)
        df: Dict[str, int] = {}
        for doc in self.documents:
            for term in set(doc.tokens):
                df[term] = df.get(term, 0) + 1
        self._idf = {
            term: math.log((1.0 + n) / (1.0 + freq)) + 1.0
            for term, freq in df.items()
        }
        for doc in self.documents:
            doc.vector = self._vectorize(doc.tokens)
        self._built = True

    # -- vectorisation / similarity -----------------------------------------
    def _vectorize(self, tokens: Sequence[str]) -> Dict[str, float]:
        tf = _term_frequencies(tokens)
        vec: Dict[str, float] = {}
        norm = 0.0
        for term, freq in tf.items():
            w = freq * self._idf.get(term, 1.0)
            vec[term] = w
            norm += w * w
        if norm > 0.0:
            inv = math.sqrt(norm)
            vec = {t: w / inv for t, w in vec.items()}
        return vec

    @staticmethod
    def _cosine(a: Dict[str, float], b: Dict[str, float]) -> float:
        if not a or not b:
            return 0.0
        small, large = (a, b) if len(a) <= len(b) else (b, a)
        return sum(w * large.get(t, 0.0) for t, w in small.items())

    # -- metadata relevance (ranking signal) --------------------------------
    def _metadata_field_similarity(self, doc: Document, query_terms,
                                   boost_fields) -> float:
        if not query_terms:
            return 0.0
        field_scores: List[float] = []
        for field in boost_fields:
            raw = doc.metadata.get(field)
            if raw is None:
                continue
            values = raw if isinstance(raw, (list, tuple, set)) else [raw]
            best = 0.0
            for value in values:
                vt = set(tokenize(value))
                if not vt:
                    continue
                best = max(best, len(vt & query_terms) / float(len(vt)))
            field_scores.append(best)
        if not field_scores:
            return 0.0
        return sum(field_scores) / float(len(field_scores))

    def _recency(self, doc: Document, recency_field: Optional[str],
                 halflife_days: float, today: _dt.date) -> float:
        if not recency_field:
            return 1.0
        parsed = _parse_date(doc.metadata.get(recency_field))
        if parsed is None:
            return 1.0
        age_days = max(0.0, float((today - parsed).days))
        return 0.5 ** (age_days / halflife_days)

    def metadata_relevance(self, doc: Document, query_terms,
                           boost_fields=DEFAULT_BOOST_FIELDS,
                           recency_field: Optional[str] = "date",
                           halflife_days: float = 730.0,
                           today: Optional[_dt.date] = None) -> float:
        """Metadata-driven relevance in [0, 1] used to re-rank candidates."""
        today = today or _dt.date.today()
        field_sim = self._metadata_field_similarity(doc, query_terms, boost_fields)
        recency = self._recency(doc, recency_field, halflife_days, today)
        return 0.75 * field_sim + 0.25 * recency

    # -- retrieval -----------------------------------------------------------
    def retrieve(self, query: str, *,
                 filters: Optional[dict] = None,
                 top_k: int = 5,
                 alpha: Optional[float] = None,
                 boost_fields=DEFAULT_BOOST_FIELDS,
                 recency_field: Optional[str] = "date",
                 halflife_days: float = 730.0,
                 today: Optional[_dt.date] = None) -> List[Tuple[float, Document]]:
        """Retrieve *top_k* documents after metadata filtering + ranking.

        Stage 1 - metadata filtering: only documents whose metadata satisfies
                  every predicate in *filters* become candidates.
        Stage 2 - hybrid relevance ranking: each candidate is scored as
                  alpha * semantic_similarity + (1-alpha) * metadata_relevance
                  and the best *top_k* candidates are returned, highest first.
        """
        if not self._built:
            self.build()
        if top_k <= 0:
            return []
        query_terms = set(tokenize(query))
        qvec = self._vectorize(tokenize(query))
        mix = self.alpha if alpha is None else alpha
        today = today or _dt.date.today()

        scored: List[Tuple[float, int, Document]] = []
        for idx, doc in enumerate(self.documents):
            if not matches_filters(doc.metadata, filters):
                continue  # metadata filter gates the candidate set
            semantic = self._cosine(qvec, doc.vector)
            meta = self.metadata_relevance(
                doc, query_terms, boost_fields=boost_fields,
                recency_field=recency_field, halflife_days=halflife_days,
                today=today)
            score = mix * semantic + (1.0 - mix) * meta
            scored.append((score, idx, doc))

        scored.sort(key=lambda item: (-item[0], item[1]))
        return [(score, doc) for score, _idx, doc in scored[:top_k]]

    def search(self, query: str, **kwargs) -> List[Tuple[float, Document]]:
        return self.retrieve(query, **kwargs)


# --------------------------------------------------------------------------
# Grounded answer generation (the "generation" half of RAG)
# --------------------------------------------------------------------------

class GroundedAnswerGenerator:
    """Deterministic extractive generator: answers only from retrieved docs.

    Replace with an LLM call in a production deployment; the retrieval
    contract (filtered, ranked, metadata-carrying sources) stays identical.
    """

    def __init__(self, max_sentences_per_doc: int = 2):
        self.max_sentences_per_doc = max_sentences_per_doc

    def generate(self, question: str,
                 ranked: Sequence[Tuple[float, Document]]) -> str:
        if not ranked:
            return "No grounded evidence was retrieved for this question."
        query_terms = set(tokenize(question))
        lines: List[str] = []
        for rank, (_score, doc) in enumerate(ranked, start=1):
            candidates = []
            for sentence in _sentences(doc.text):
                st = set(tokenize(sentence))
                overlap = float(len(st & query_terms)) if st else 0.0
                candidates.append((overlap, sentence))
            candidates.sort(key=lambda c: (-c[0], len(c[1])))
            chosen = 0
            for _overlap, sentence in candidates:
                if chosen >= self.max_sentences_per_doc:
                    break
                lines.append(f"[{rank}] {sentence}")
                chosen += 1
            if chosen == 0:
                first = _sentences(doc.text)
                if first:
                    lines.append(f"[{rank}] {first[0]}")
        return "Based on the retrieved documents:\n" + "\n".join(lines)


class RAGPipeline:
    """End-to-end pipeline: metadata-filtered retrieval -> grounded answer."""

    def __init__(self, index: MetadataRAGIndex,
                 generator: Optional[GroundedAnswerGenerator] = None,
                 top_k: int = 3):
        self.index = index
        self.generator = generator or GroundedAnswerGenerator()
        self.top_k = top_k

    def ask(self, question: str, *, filters: Optional[dict] = None,
            top_k: Optional[int] = None, **retrieve_kwargs) -> Dict[str, object]:
        top_k = top_k or self.top_k
        ranked = self.index.retrieve(question, filters=filters, top_k=top_k,
                                     **retrieve_kwargs)
        answer = self.generator.generate(question, ranked)
        return {
            "question": question,
            "filters": filters,
            "top_k": top_k,
            "answer": answer,
            "sources": [doc.to_public_dict(score) for score, doc in ranked],
        }


