def run_self_tests(rag: MetadataRAG) -> None:
    print("=" * 78)
    print("SELF-TESTS (metadata filtering + ranking sanity)")
    print("=" * 78)
    checks = []

    # (name, boolean, detail)
    def check(name, ok, detail=""):
        checks.append(ok)
        print("  [%s] %s %s" % ("PASS" if ok else "FAIL", name,
                                ("- " + detail) if detail else ""))

    # coverage: every corpus token appears inside at least one chunk of its doc
    coverage_ok = True
    for did, d in rag.documents.items():
        doc_tokens = set(tokenize(d.get("content", "")))
        chunk_tokens = set()
        for c in rag.chunks:
            if c.doc_id == did:
                chunk_tokens.update(c.terms)
        missing = doc_tokens - chunk_tokens
        if missing:
            coverage_ok = False
            print("    (doc %s missing tokens: %s)" % (did, sorted(missing)[:8]))
    check("chunking covers 100%% of source tokens", coverage_ok)

    # filter: category equality
    hits = rag.retrieve("postgres", top_k=10, filters={"category": "engineering"})
    cats = {h.chunk.metadata["category"] for h in hits}
    check("filter category=engineering returns only engineering", hits and cats == {"engineering"})

    # filter: access level range
    hits = rag.retrieve("policy", top_k=20, filters={"access_level": {"$lte": 2}})
    leaked = sorted({h.chunk.metadata["doc_id"] for h in hits if h.chunk.metadata["access_level"] > 2})
    check("access_level<=2 never leaks level 3/4 docs", not leaked, "leaked=%s" % leaked)

    # filter: tag substring
    hits = rag.retrieve("retrieval", top_k=20, filters={"tags": {"$contains": "rag"}})
    docs = {h.chunk.doc_id for h in hits}
    check("tags contains 'rag' returns only d3/d8", docs == {"d3", "d8"}, "docs=%s" % sorted(docs))

    # filter: date range (ISO dates compared as dates)
    hits = rag.retrieve("scaling", top_k=20, filters={"date": {"$gte": "2024-06-01"}})
    dates = [h.chunk.metadata["date"] for h in hits]
    check("date>=2024-06-01 excludes older docs",
          all(d >= "2024-06-01" for d in dates) and bool(dates))

    # ranking sanity: topical queries put the obvious doc first
    cases = [
        ("How do we tune postgres connection pooling and vacuum scheduling?",
         {"category": "engineering"}, {"d1"}),
        ("kubernetes autoscaling, cluster autoscaler and node scale limits",
         {"category": "engineering"}, {"d2"}),
        ("prompt guardrails against prompt injection and unsafe output",
         {"category": "research"}, {"d4"}),
        ("2025 budget planning with cost centers and committed cloud spend",
         {"category": "finance"}, {"d9"}),
    ]
    for q, filt, expect in cases:
        top = rag.retrieve(q, top_k=1, filters=filt)
        ok = bool(top) and top[0].chunk.doc_id in expect
        check("top-1 for %r is in %s" % (_short(q, 45), sorted(expect)),
              ok, ("got %s" % top[0].chunk.doc_id) if top else "no hits")

    # empty result handled gracefully
    hits = rag.retrieve("anything", top_k=5,
                        filters={"category": "finance", "access_level": {"$lte": 1}})
    check("no match -> empty result, no crash", hits == [])

    print("  -> %d/%d self-tests passed" % (sum(checks), len(checks)))
    print()
    if not all(checks):
        sys.exit(1)


