def _doc(doc_id: str, title: str, category: str, tags: List[str], author: str,
         date: str, audience: str, body: str) -> Document:
    return Document(
        doc_id=doc_id,
        text=title + ". " + body,
        metadata={
            "title": title,
            "category": category,
            "tags": list(tags),
            "author": author,
            "date": date,
            "year": int(date[:4]),
            "audience": audience,
        },
    )


